using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer.Tools;

[McpServerToolType]
public static class EchoTool
{
    [McpServerTool, Description("Echoes back the provided message.")]
    public static string Echo([Description("The message to echo")] string message)
        => $"Echo: {message}";
}

using ModelContextProtocol.Server;

namespace McpHttpServer.Resources;

[McpServerResourceType]
public static class ConfigResource
{
    [McpServerResource(
        Uri = "config://app/settings",
        Name = "App Settings",
        Description = "Returns the application configuration data.",
        MimeType = "application/json")]
    public static string GetAppSettings()
    {
        var config = new
        {
            AppName = "McpHttpServer",
            Version = "1.0.0",
            Environment = "Development",
            Features = new { EnableLogging = true, MaxRetries = 3 }
        };

        return System.Text.Json.JsonSerializer.Serialize(config,
            new System.Text.Json.JsonSerializerOptions { WriteIndented = true });
    }
}

